"""Shared value encodings and errors for the command-line data query engine."""
import json
import math
import re


class ToolError(Exception):
    def __init__(self, message, code=1):
        super().__init__(message)
        self.code = code


def float_text(value, json_mode=True):
    """The compact decimal representation used for floating-point result values."""
    if not math.isfinite(value):
        raise ToolError('json: unsupported value: ' + ('NaN' if math.isnan(value) else '+Inf' if value > 0 else '-Inf'))
    s = repr(value)
    if value == 0:
        return '-0' if math.copysign(1, value) < 0 else '0'
    if json_mode and 1e-6 <= abs(value) < 1e21:
        if 'e' in s:
            from decimal import Decimal
            s = format(Decimal(s), 'f')
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return s
    if not json_mode and (abs(value) >= 1e6 or abs(value) < 1e-4) and 'e' not in s:
        from decimal import Decimal
        s = format(Decimal(s).normalize(), 'e')
    if s.endswith('.0'):
        s = s[:-2]
    if 'e' in s:
        a, b = s.split('e')
        if a.endswith('.0'):
            a = a[:-2]
        exponent = int(b)
        s = a + 'e' + ('+' if exponent >= 0 else '-') + (str(abs(exponent)) if json_mode else str(abs(exponent)).zfill(2))
    return s


def quote_string(s):
    # Values use JSON escaping, including the HTML-safe escapes.
    s = json.dumps(str(s), ensure_ascii=False, separators=(',', ':'))
    s = s.replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    s = s.replace('\u2028', '\\u2028').replace('\u2029', '\\u2029')
    # An invalid Unicode scalar in an input is replaced, not sent to stdout.
    return ''.join('\ufffd' if 0xd800 <= ord(c) <= 0xdfff else c for c in s)


def quote_key(s):
    # Record keys are quoted as ASCII strings. Non-BMP runes use eight hex digits.
    out = ['"']
    escapes = {'"': '\\"', '\\': '\\\\', '\n': '\\n', '\r': '\\r', '\t': '\\t', '\b': '\\b', '\f': '\\f'}
    for c in str(s):
        n = ord(c)
        if c in escapes:
            out.append(escapes[c])
        elif n < 32 or n == 127:
            out.append('\\x%02x' % n)
        elif n > 127:
            out.append(('\\u%04x' if n <= 65535 else '\\U%08x') % n)
        else:
            out.append(c)
    out.append('"')
    return ''.join(out)


def json_encode(value, record_keys=False, sort_keys=False):
    if value is None:
        return 'null'
    if value is True:
        return 'true'
    if value is False:
        return 'false'
    if isinstance(value, float):
        return float_text(value)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, bytes):
        value = value.decode('utf-8', 'replace')
    if isinstance(value, str):
        return quote_string(value)
    if isinstance(value, dict):
        items = sorted(value.items()) if sort_keys else value.items()
        quote = quote_key if record_keys else quote_string
        return '{' + ','.join(quote(k) + ':' + json_encode(v, False, sort_keys) for k, v in items) + '}'
    if isinstance(value, (list, tuple)):
        return '[' + ','.join(json_encode(v, False, sort_keys) for v in value) + ']'
    return quote_string(str(value))


def encode_rows(rows):
    return '[' + ',\n'.join(json_encode(row, record_keys=True) for row in rows) + ']'


def go_string(x):
    if x is None:
        return '<nil>'
    if isinstance(x, bool):
        return str(x).lower()
    if isinstance(x, float):
        return float_text(x, False)
    if isinstance(x, bytes):
        return x.decode('utf-8', 'replace')
    return str(x)


def parse_number(text):
    if not isinstance(text, str) or text != text.strip() or not text:
        return text
    try:
        if re.match(r'^[+-]?0[xX]', text) and 'p' in text.lower():
            return float.fromhex(text)
        if re.match(r'^[+-]?(?:(?:\d[\d_]*\.?[\d_]*|\.[\d_]+)(?:[eE][+-]?[\d_]+)?|NaN|Inf(?:inity)?)$', text, re.I):
            return float(text)
    except (ValueError, OverflowError):
        pass
    return text
