"""Plain-text table output."""
import math
import re
import unicodedata
from common import json_encode, float_text, ToolError


def width(s):
    total = 0
    # ANSI color escapes, when present, don't occupy table cells.
    s = re.sub(r'\x1b\[[0-9;]*m', '', s)
    for c in s:
        if c in '\t\r\n' or unicodedata.category(c) in ('Mn', 'Me', 'Cf', 'Cc'):
            continue
        total += 2 if unicodedata.east_asian_width(c) in ('W', 'F') else 1
    return total


def wrap_line(s, limit=30):
    if width(s) <= limit:
        return [s]
    words = s.split()
    if not words:
        return ['']
    lines, line = [], ''
    for word in words:
        if line and width(line) + 1 + width(word) > limit:
            lines.append(line)
            line = word
        else:
            line += (' ' if line else '') + word
    if line:
        lines.append(line)
    return lines or ['']


def text(value):
    if value is None:
        return 'null'
    if value is True:
        return 'true'
    if value is False:
        return 'false'
