"""Structural type inference, including nullable and heterogeneous columns."""
import copy

UNKNOWN = {'kind': 'unknown'}
NULL = {'kind': 'scalar', 'scalar': 'null'}


def has_variant(shape, needle):
    return shape == needle or (shape['kind'] == 'varied' and any(has_variant(v, needle) for v in shape['varied']))


def merge(a, b):
    if a == b or has_variant(a, b):
        return a
    ka, kb = a['kind'], b['kind']
    if ka == kb == 'object':
        old, new = a['object'], b['object']
        obj = {}
        for k in old:
            obj[k] = merge(old[k], new[k] if k in new else NULL)
        for k in new:
            if k not in old:
                obj[k] = merge(new[k], NULL)
        return {'kind': 'object', 'object': obj}
    if ka == kb == 'array':
        # Different array shapes are unified at their element level.
        return merge(a['array'], b['array'])
    return {'kind': 'varied', 'varied': [a, b]}


def infer(value):
    if value is None:
        return UNKNOWN.copy()
    if isinstance(value, bool):
        return {'kind': 'scalar', 'scalar': 'boolean'}
    if isinstance(value, (int, float)):
        return {'kind': 'scalar', 'scalar': 'number'}
    if isinstance(value, (str, bytes)):
        return {'kind': 'scalar', 'scalar': 'string'}
    if isinstance(value, dict):
        return {'kind': 'object', 'object': {k: infer(v) for k, v in value.items()}}
    if isinstance(value, list):
        if not value:
            item = UNKNOWN.copy()
        else:
            item = infer(value[0])
            for v in value[1:]:
                item = merge(item, infer(v))
        return {'kind': 'array', 'array': item}
    return UNKNOWN.copy()


def describe(s, level=0):
    indent = '  ' * level
    k = s['kind']
    if k == 'unknown':
        return indent + 'Unknown'
    if k == 'scalar':
        return indent + s['scalar']
    if k == 'array':
        return indent + 'Array of\n' + describe(s['array'], level+1)
    if k == 'object':
        parts = [indent + 'Object of']
        for name, child in sorted(s['object'].items()):
            parts.extend(['  ' * (level+1) + name + ' of', describe(child, level+2)])
        return '\n'.join(parts)
    if k == 'varied':
        return indent + 'Varied of\n' + ' or\n'.join(describe(v, level+1) for v in s['varied'])
    return indent + 'Unknown'


def sql_type(s):
    if s['kind'] == 'scalar':
        return {'boolean': 'BOOLEAN', 'number': 'REAL'}.get(s['scalar'], 'TEXT')
    if s['kind'] == 'varied':
        v = [x for x in s['varied'] if x != NULL]
        if len(v) == 1:
            return sql_type(v[0])
    return 'TEXT'


def columns(s, prefix=(), sort=False):
    """Yield column name, source path and affinity for a row object."""
    if s['kind'] == 'object':
        items = s['object'].items()
        if sort:
            items = sorted(items)
        for k, v in items:
            yield from columns(v, prefix + (k,), sort)
    elif prefix:
        yield '.'.join(prefix), prefix, sql_type(s)


def get_path(obj, path):
    for part in path:
        if not isinstance(obj, dict):
            return None
        obj = obj.get(part)
    return obj
