"""Readers for text tables, structured text, and XML-based spreadsheets.

All readers produce ordinary values; SQL type selection is kept separate from
file decoding. This also permits unqueried JSON to retain its original layout.
"""
import datetime
import io
import json
import os
import posixpath
import re
import struct
import zipfile
import xml.etree.ElementTree as ET
from common import ToolError, encode_rows, json_encode, parse_number

MIMES = {
    'json': 'application/json',
    'csv': 'text/csv',
    'tsv': 'text/tab-separated-values',
    'ndjson': 'application/jsonlines',
    'jsonl': 'application/jsonlines',
    'yaml': 'application/yaml',
    'yml': 'application/yaml',
    'txt': 'text/plain',
    'logfmt': 'application/logfmt',
    'xls': 'application/vnd.ms-excel',
    'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'xlsm': 'application/vnd.ms-excel.sheet.macroEnabled.12',
    'ods': 'application/vnd.oasis.opendocument.spreadsheet',
    'parquet': 'application/parquet',
    'avro': 'application/avro',
    'orc': 'application/orc',
}
KIND_FOR_MIME = {v: k for k, v in MIMES.items()}
KIND_FOR_MIME.update({'application/jsonlines': 'ndjson', 'application/yaml': 'yaml'})


def file_kind(path, specified=None):
    if specified is not None:
        mime = specified if '/' in specified else MIMES.get(specified)
    else:
        ext = os.path.splitext(path)[1][1:]
        mime = MIMES.get(ext.lower())
    if not mime:
        raise ToolError('Unknown mimetype for file: ' + path + '.')
    return KIND_FOR_MIME.get(mime, 'txt')


def column_letter(i):
    out = ''
    i += 1
    while i:
        i, r = divmod(i-1, 26)
        out = chr(65+r) + out
    return out


def records(rows, numbers=False):
    if not rows:
        return []
    header = rows[0]
    out = []
    for row in rows[1:]:
        obj = {}
        for i in range(max(len(header), len(row))):
            key = header[i] if i < len(header) and header[i] else column_letter(i)
            val = row[i] if i < len(row) else None
            obj[str(key)] = parse_number(val) if numbers else val
        out.append(obj)
    return out


def csv_read(text, sep=','):
    text = text.replace('\r\n', '\n')
    n, i, line, col = len(text), 0, 1, 1
    rows = []
    while i < n:
        if text[i] == '\n':
            i += 1; line += 1; col = 1
            continue
        row = []
        while True:
            field = []
            if i < n and text[i] == '"':
                start_line = line
                i += 1; col += 1
                done = False
                while i < n:
                    ch = text[i]
                    if ch == '"':
                        if i+1 < n and text[i+1] == '"':
                            field.append('"'); i += 2; col += 2
                            continue
                        if i+1 == n or text[i+1] in (sep, '\n', '\r'):
                            i += 1; col += 1; done = True
                            break
                        raise ToolError(f'parse error on line {line}, column {col}: extraneous or missing " in quoted-field')
                    field.append(ch)
