}
KIND_FOR_MIME = {v: k for k, v in MIMES.items()}
KIND_FOR_MIME.update({'application/jsonlines': 'ndjson', 'application/yaml': 'yaml'})


def file_kind(path, specified=None):
    if specified is not None:
        mime = specified if '/' in specified else MIMES.get(specified)
    else:
        ext = os.path.splitext(path)[1][1:]
        mime = MIMES.get(ext.lower())
    if not mime:
        raise ToolError('Unknown mimetype for file: ' + path + '.')
    return KIND_FOR_MIME.get(mime, 'txt')


def column_letter(i):
    out = ''
    i += 1
    while i:
        i, r = divmod(i-1, 26)
        out = chr(65+r) + out
    return out


def records(rows, numbers=False):
    if not rows:
        return []
    header = rows[0]
    out = []
    for row in rows[1:]:
        obj = {}
        for i in range(max(len(header), len(row))):
            key = header[i] if i < len(header) and header[i] else column_letter(i)
            val = row[i] if i < len(row) else None
            obj[str(key)] = parse_number(val) if numbers else val
        out.append(obj)
    return out


def csv_read(text, sep=','):
    text = text.replace('\r\n', '\n')
    n, i, line, col = len(text), 0, 1, 1
    rows = []
    while i < n:
        if text[i] == '\n':
            i += 1; line += 1; col = 1
            continue
        row = []
        while True:
            field = []
            if i < n and text[i] == '"':
                start_line = line
                i += 1; col += 1
                done = False
                while i < n:
                    ch = text[i]
                    if ch == '"':
                        if i+1 < n and text[i+1] == '"':
                            field.append('"'); i += 2; col += 2
                            continue
                        if i+1 == n or text[i+1] in (sep, '\n', '\r'):
                            i += 1; col += 1; done = True
                            break
                        raise ToolError(f'parse error on line {line}, column {col}: extraneous or missing " in quoted-field')
                    field.append(ch)
                    i += 1
                    if ch == '\n':
                        line += 1; col = 1
                    else:
                        col += len(ch.encode('utf-8'))
                if not done:
                    # The reader reports an unterminated final newline on its original line.
                    eline, ecol = line, col
                    if text.endswith('\n'):
                        eline -= 1
                        ecol = len(text.rstrip('\n').rsplit('\n', 1)[-1].encode())+2
                    raise ToolError(f'parse error on line {eline}, column {ecol}: extraneous or missing " in quoted-field')
            else:
                while i < n and text[i] not in (sep, '\n'):
                    ch = text[i]
                    if ch == '"':
                        raise ToolError(f'parse error on line {line}, column {col}: bare " in non-quoted-field')
                    field.append(ch); i += 1; col += len(ch.encode('utf-8'))
            val = ''.join(field)
            if i == n and val.endswith('\r'):
                val = val[:-1]
            row.append(val)
            if i < n and text[i] == sep:
                i += 1; col += 1
                continue
            if i < n and text[i] == '\r':
                i += 1; col += 1
            if i < n and text[i] == '\n':
                i += 1; line += 1; col = 1
            break
        rows.append(row)
    return rows


def json_error(text, exc):
    if not text.strip():
        return 'EOF'
    pos = exc.pos
    if pos >= len(text):
        return 'unexpected EOF'
    c = text[pos]
    q = "'\\n'" if c == '\n' else "'\\r'" if c == '\r' else "'\\t'" if c == '\t' else repr(c)
    # JSON's three literal tokens get especially useful diagnostics.
    start = pos
    while start > 0 and text[start-1].isalpha():
        start -= 1
    token = text[start:]
    for literal in ('null', 'true', 'false'):
        if token.startswith(literal[0]):
            for idx, letter in enumerate(literal):
                if idx >= len(token):
                    return 'unexpected EOF'
                if token[idx] != letter:
                    return 'invalid character '+repr(token[idx])+' in literal '+literal+" (expecting '"+letter+"')"
    if exc.msg.startswith('Invalid control character'):
        return 'invalid character '+q+' in string literal'
    if exc.msg.startswith('Unterminated string'):
        return 'unexpected EOF'
    if exc.msg == 'Expecting property name enclosed in double quotes':
        return 'invalid character '+q+' looking for beginning of object key string'
    if exc.msg == "Expecting ':' delimiter":
        return 'invalid character '+q+' after object key'
    if exc.msg == "Expecting ',' delimiter":
        return 'invalid character '+q+' after object key:value pair'
    return 'invalid character '+q+' looking for beginning of value'


def json_values(text, multiple=False):
    decoder = json.JSONDecoder(parse_int=float, parse_float=float,
                               parse_constant=lambda s: (_ for _ in ()).throw(ValueError(s)))
    out = []
    offset = 0
    while True:
        while offset < len(text) and text[offset].isspace():
            offset += 1
        if offset == len(text):
            if not out and not multiple:
                raise ToolError('EOF')
            break
        try:
            value, offset = decoder.raw_decode(text, offset)
        except json.JSONDecodeError as exc:
            raise ToolError(json_error(text, exc)) from None
        except ValueError as exc:
            raise ToolError('invalid character '+repr(str(exc)[0])+' looking for beginning of value') from None
        out.append(value)
        if not multiple:
            break
    return out if multiple else out[0]


def logfmt_read(text):
    result = []
    for lineno, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        fields = {}
        i = 0
        while i < len(line):
            while i < len(line) and line[i].isspace():
                i += 1
            if i == len(line):
                break
            start = i
            while i < len(line) and not line[i].isspace() and line[i] != '=':
                if line[i] == '"':
                    raise ToolError(f'logfmt syntax error at pos {i+1} on line {lineno}: unexpected \'"\'')
                i += 1
            key = line[start:i]
            val = ''
            if i < len(line) and line[i] == '=':
                i += 1
                if i < len(line) and line[i] == '"':
                    start = i
                    i += 1
                    while i < len(line):
                        if line[i] == '\\':
                            i += 2
                        elif line[i] == '"':
                            i += 1
                            break
                        else:
                            i += 1
                    try:
                        val = json.loads(line[start:i])
                    except Exception:
                        raise ToolError(f'logfmt syntax error at pos {start+1} on line {lineno}: unterminated quoted value') from None
                else:
                    start = i
                    while i < len(line) and not line[i].isspace():
                        i += 1
                    val = line[start:i]
            if key:
                fields[key] = val
        result.append(fields)
    return result


def _yaml_split(s, delimiter=','):
    pieces, start, depth, quote, escaped = [], 0, 0, None, False
    for i, c in enumerate(s):
        if quote:
            if escaped:
                escaped = False
            elif c == '\\' and quote == '"':
                escaped = True
            elif c == quote:
                quote = None
        elif c in '\'"':
            quote = c
        elif c in '[{':
            depth += 1
        elif c in ']}':
            depth -= 1
        elif c == delimiter and depth == 0:
            pieces.append(s[start:i]); start = i+1
    pieces.append(s[start:])
    return pieces


def yaml_scalar(s):
    s = s.strip()
    if not s:
        return None
    if s.startswith('!!str '):
        return str(yaml_scalar(s[6:]))
    if s.startswith('"'):
        try:
            return json.loads(s)
        except Exception:
            return s[1:-1]
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1].replace("''", "'")
    if s.startswith('[') and s.endswith(']'):
        return [yaml_scalar(v) for v in _yaml_split(s[1:-1])] if s[1:-1].strip() else []
    if s.startswith('{') and s.endswith('}'):
        out = {}
        for p in _yaml_split(s[1:-1]):
            if not p.strip():
                continue
            parts = _yaml_split(p, ':')
            if len(parts) > 1:
                out[str(yaml_scalar(parts[0]))] = yaml_scalar(':'.join(parts[1:]))
        return out
    s = re.split(r'\s+#', s, 1)[0].strip()
    if s in ('null', 'Null', 'NULL', '~'):
        return None
    if s in ('true', 'True', 'TRUE', 'false', 'False', 'FALSE'):
        return s.lower() == 'true'
    try:
        t = s.replace('_', '')
        if re.fullmatch(r'[+-]?0[0-7]+', t):
            return int(t, 8)
        if re.fullmatch(r'[+-]?0[xX][\da-fA-F]+|[+-]?0[oO][0-7]+|[+-]?0[bB][01]+', t):
            return int(t, 0)
        if re.fullmatch(r'[+-]?\d+', t):
            return int(t)
        if re.fullmatch(r'[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?', t):
            return float(t)
    except ValueError:
        pass
    if re.match(r'^\d{4}-\d\d-\d\d(?:$|[Tt ])', s):
        try:
            d = datetime.datetime.fromisoformat(s.replace('t', 'T').replace('Z', '+00:00'))
            return d.isoformat(timespec='seconds').replace('+00:00', 'Z') + ('Z' if d.tzinfo is None else '')
        except ValueError:
            pass
    return s


def yaml_read_document(text):
    lines = text.splitlines()
    # Retain indentation; comments and empty lines don't form nodes.
    entries = [(len(s)-len(s.lstrip(' ')), s.lstrip(' '), i) for i, s in enumerate(lines)
               if s.strip() and not s.lstrip().startswith(('#', '%', '...'))]
    anchors = {}
    def scalar(s):
        if s.startswith('*'):
            return anchors.get(s[1:], None)
        return yaml_scalar(s)
    def kv(s):
        quote = None; depth = 0
        for i, ch in enumerate(s):
            if quote:
                if ch == quote and (i == 0 or s[i-1] != '\\'):
                    quote = None
            elif ch in '\'"': quote = ch
            elif ch in '[{': depth += 1
            elif ch in ']}': depth -= 1
            elif ch == ':' and depth == 0 and (i+1 == len(s) or s[i+1].isspace()):
                return s[:i], s[i+1:].lstrip()
        return None
    def value_after(s, at, indent, source):
        anchor = None
        if s.startswith('&'):
            bits = s.split(None, 1)
            anchor = bits[0][1:]
            s = bits[1] if len(bits) > 1 else ''
        if s.startswith(('|', '>')):
            next_at = at
            while next_at < len(entries) and entries[next_at][0] > indent:
                next_at += 1
            endline = entries[next_at][2] if next_at < len(entries) else len(lines)
            block = lines[source+1:endline]
            nonempty = [len(x)-len(x.lstrip(' ')) for x in block if x.strip()]
            trim = min(nonempty) if nonempty else 0
            block = [x[trim:] for x in block]
            value = '\n'.join(block)
            if s.startswith('>'):
                value = re.sub(r'(?<!\n)\n(?!\n)', ' ', value)
            value = value.rstrip('\n') + ('' if '-' in s else '\n')
            at = next_at
        elif s:
            value = scalar(s)
        elif at < len(entries) and entries[at][0] > indent:
            value, at = node(at, entries[at][0])
        else:
            value = None
        if anchor is not None:
            anchors[anchor] = value
        return value, at
    def node(at, indent):
        if at >= len(entries): return None, at
        seq = entries[at][1] == '-' or entries[at][1].startswith('- ')
        obj = [] if seq else {}
        while at < len(entries) and entries[at][0] == indent:
            _, s, source = entries[at]; at += 1
            if seq:
                if not (s == '-' or s.startswith('- ')):
                    break
                s = s[1:].lstrip()
                pair = kv(s)
                if pair:
                    key, val = pair
                    item = {}
                    value, at = value_after(val, at, indent+2, source)
                    item[str(scalar(key))] = value
                    if at < len(entries) and entries[at][0] > indent:
                        extra, at = node(at, entries[at][0])
                        if isinstance(extra, dict): item.update(extra)
                    obj.append(item)
                else:
                    value, at = value_after(s, at, indent, source)
                    obj.append(value)
            else:
                pair = kv(s)
                if pair is None:
                    return scalar(s), at
                key, val = pair
                value, at = value_after(val, at, indent, source)
                key = str(scalar(key))
                if key == '<<' and isinstance(value, dict):
                    obj.update(value)
                else:
                    obj[key] = value
        return obj, at
    return node(0, entries[0][0])[0] if entries else None


def yaml_read(text):
    docs = re.split(r'^---\s*(?:#.*)?$', text, flags=re.M)
    if len(docs) > 1 and not docs[0].strip():
        docs.pop(0)
    values = [yaml_read_document(d) for d in docs]
    if len(values) == 1:
        return values[0], json_encode(values[0], sort_keys=True)+'\n'
    return values, encode_rows(values)


XNS = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
RNS = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'


def _cell_format(value, numfmt, custom, epoch):
    try:
        v = float(value)
    except ValueError:
        return value
    # A custom number format is not always applied by spreadsheet importers.
    fmt = custom.get(numfmt, '')
    if numfmt in (14, 15, 16, 17, 18, 19, 20, 21, 22, 45, 46, 47) or (fmt and re.search(r'[dyh]', re.sub(r'"[^"]*"', '', fmt), re.I)):
        try:
            date = epoch + datetime.timedelta(days=v)
        except (ValueError, OverflowError):
            return value
        formats = {14:'%m-%d-%y',15:'%d-%b-%y',16:'%d-%b',17:'%b-%y',18:'%I:%M %p',19:'%I:%M:%S %p',20:'%H:%M',21:'%H:%M:%S',22:'%m/%d/%y %H:%M',45:'%M:%S',47:'%M%S.0'}
        if numfmt in formats:
            return date.strftime(formats[numfmt])
        # Imported custom formats leave the original serial value untouched.
        return value
    if numfmt == 1:
        return str(round(v))
    if numfmt == 2:
        return f'{v:.2f}'
    if numfmt == 3:
        return f'{v:,.0f}'
    if numfmt == 4:
        return f'{v:,.2f}'
    if numfmt == 9:
        return f'{v*100:.0f}%'
    if numfmt == 10:
        return f'{v*100:.2f}%'
    if numfmt == 11:
        return f'{v:.2E}'
    return value


def xlsx_read(raw, numbers=False):
    try:
        z = zipfile.ZipFile(io.BytesIO(raw))
    except zipfile.BadZipFile:
        raise ToolError('zip: not a valid zip file') from None
    with z:
        try:
            wb = ET.fromstring(z.read('xl/workbook.xml'))
        except KeyError:
            raise ToolError('zip: not a valid zip file') from None
        shared = []
        if 'xl/sharedStrings.xml' in z.namelist():
            root = ET.fromstring(z.read('xl/sharedStrings.xml'))
            shared = [''.join(e.itertext()) for e in root.findall(XNS+'si')]
        styles, custom = [], {}
        if 'xl/styles.xml' in z.namelist():
            root = ET.fromstring(z.read('xl/styles.xml'))
            custom = {int(x.get('numFmtId')):x.get('formatCode','') for x in root.findall(XNS+'numFmts/'+XNS+'numFmt')}
            styles = [int(x.get('numFmtId','0')) for x in root.findall(XNS+'cellXfs/'+XNS+'xf')]
        rels = {}
        if 'xl/_rels/workbook.xml.rels' in z.namelist():
            for e in ET.fromstring(z.read('xl/_rels/workbook.xml.rels')):
                target = e.get('Target','')
                rels[e.get('Id')] = target.lstrip('/') if target.startswith('/') else posixpath.normpath('xl/'+target)
        prop = wb.find(XNS+'workbookPr')
        epoch = datetime.datetime(1904,1,1) if prop is not None and prop.get('date1904') in ('true','1') else datetime.datetime(1899,12,30)
        sheets = {}
        for index, sh in enumerate(wb.findall(XNS+'sheets/'+XNS+'sheet')):
            target = rels.get(sh.get(RNS+'id'), f'xl/worksheets/sheet{index+1}.xml')
            root = ET.fromstring(z.read(target))
            rows = []
            for r in root.findall(XNS+'sheetData/'+XNS+'row'):
                ri = int(r.get('r', str(len(rows)+1)))-1
                while len(rows) < ri:
                    rows.append([])
                vals = []
                for c in r.findall(XNS+'c'):
                    ref = c.get('r', '')
                    if ref:
                        ci = 0
                        for letter in re.match(r'[A-Za-z]+', ref)[0].upper(): ci = ci*26+ord(letter)-64
                        ci -= 1
                    else: ci = len(vals)
                    while len(vals) <= ci: vals.append('')
                    t = c.get('t','n')
                    v = c.find(XNS+'v')
                    val = v.text if v is not None and v.text is not None else ''
                    if t == 's':
                        val = shared[int(val)] if val else ''
                    elif t == 'inlineStr':
                        el = c.find(XNS+'is')
                        val = ''.join(el.itertext()) if el is not None else ''
                    elif t == 'b':
                        val = 'TRUE' if val == '1' else 'FALSE'
                    elif t in ('n',''):
                        s = int(c.get('s','0'))
                        val = _cell_format(val, styles[s] if s < len(styles) else 0, custom, epoch)
                    vals[ci] = val
                while vals and vals[-1] == '': vals.pop()
                rows.append(vals)
            while rows and not rows[-1]: rows.pop()
            sheets[sh.get('name', 'Sheet'+str(index+1))] = records(rows, numbers)
        return next(iter(sheets.values())) if len(sheets) == 1 else sheets


TNS = '{urn:oasis:names:tc:opendocument:xmlns:table:1.0}'
TEXTNS = '{urn:oasis:names:tc:opendocument:xmlns:text:1.0}'
OFFICENS = '{urn:oasis:names:tc:opendocument:xmlns:office:1.0}'


def ods_read(raw, numbers=False):
    try:
        z = zipfile.ZipFile(io.BytesIO(raw))
    except zipfile.BadZipFile:
        raise ToolError('zip: not a valid zip file') from None
    with z:
        root = ET.fromstring(z.read('content.xml'))
    def content(el):
        out = el.text or ''
        for e in el:
            if e.tag == TEXTNS+'s':
                out += ' '*int(e.get(TEXTNS+'c', '1'))
            elif e.tag == TEXTNS+'line-break':
                out += '\n'
            elif e.tag != TEXTNS+'tab':
                out += content(e)
            out += e.tail or ''
        return out
    sheets = {}
    for sheet in root.findall('.//'+TNS+'table'):
        rows = []
        for row in sheet.findall('.//'+TNS+'table-row'):
            vals = []
            for c in row:
                if c.tag not in (TNS+'table-cell', TNS+'covered-table-cell'): continue
                paras = c.findall(TEXTNS+'p')
                val = '\n'.join(content(p) for p in paras)
                repeat = min(int(c.get(TNS+'number-columns-repeated', '1')), 20000)
                vals.extend([val]*repeat)
            while vals and vals[-1] == '': vals.pop()
            repeat = min(int(row.get(TNS+'number-rows-repeated','1')), 20000)
            rows.extend([vals]*repeat)
        while rows and not rows[-1]: rows.pop()
        sheets[sheet.get(TNS+'name', 'Sheet1')] = records(rows, numbers)
    return next(iter(sheets.values())) if len(sheets) == 1 else sheets


class DataFile:
    def __init__(self, path, raw, kind, numbers=False):
        self.path, self.kind = path, kind
        self.serialized = None
        if kind in ('json','csv','tsv','ndjson','jsonl','yaml','yml','logfmt','txt'):
            text = raw.decode('utf-8','replace')
        if kind == 'json':
            self.data = json_values(text)
            self.serialized = text
        elif kind in ('csv','tsv'):
            self.data = records(csv_read(text, ',' if kind == 'csv' else '\t'), numbers)
        elif kind in ('ndjson','jsonl'):
            self.data = json_values(text, True)
        elif kind in ('yaml','yml'):
            self.data, self.serialized = yaml_read(text)
        elif kind == 'logfmt':
            self.data = logfmt_read(text)
        elif kind == 'txt':
            self.data = text
            self.serialized = json_encode(text)
        elif kind in ('xls','xlsx','xlsm'):
            self.data = xlsx_read(raw, numbers)
        elif kind == 'ods':
            self.data = ods_read(raw, numbers)
        elif kind in ('parquet','orc','avro'):
            from columnar import parquet_read, orc_read, avro_read
            self.data = {'parquet':parquet_read, 'orc':orc_read, 'avro':avro_read}[kind](raw)
        else:
            self.data = raw.decode('utf-8','replace')
        if self.serialized is None:
            self.serialized = encode_rows(self.data) if isinstance(self.data, list) else json_encode(self.data)
