"""SQL scalar and aggregate functions implemented over standard-library types."""
import base64
import datetime as dt
import email.utils
import hashlib
import math
import re
import statistics
import urllib.parse
from collections import Counter
from common import json_encode, ToolError


def string(v):
    if isinstance(v, str): return v
    if isinstance(v, bytes): return v.decode('utf-8', 'replace')
    return json_encode(v)


def number(v):
    if v is None: return 0.0
    try: return float(v)
    except (ValueError, TypeError, OverflowError): return 0.0


def integer(v):
    try: return int(number(v))
    except (ValueError, OverflowError): return 0


def date_value(value):
    s = string(value).strip()
    if re.fullmatch(r'[-+]?\d{10}(?:\d{3}){0,3}', s):
        try:
            denom = 10**max(0,len(s.lstrip('+-'))-10)
            return dt.datetime.fromtimestamp(int(s)/denom, dt.timezone.utc)
        except (ValueError, OverflowError, OSError): return None
    if re.fullmatch(r'\d{4}', s):
        try: return dt.datetime(int(s),1,1,tzinfo=dt.timezone.utc)
        except ValueError: return None
    try:
        d = dt.datetime.fromisoformat(s.replace('Z', '+00:00').replace('z','+00:00'))
        return d if d.tzinfo else d.replace(tzinfo=dt.timezone.utc)
    except ValueError: pass
    try:
        d = email.utils.parsedate_to_datetime(s)
        return d if d.tzinfo else d.replace(tzinfo=dt.timezone.utc)
    except (ValueError, TypeError): pass
    for fmt in ('%Y/%m/%d','%m/%d/%Y','%m/%d/%y','%Y-%m-%d %H:%M:%S','%Y/%m/%d %H:%M:%S','%m/%d/%Y %H:%M:%S','%b %d, %Y','%B %d, %Y','%d %b %Y','%d-%b-%Y','%d-%b-%y','%Y%m%d','%m-%d-%Y','%Y-%m-%dT%H:%M:%S.%f%z'):
        try:
            return dt.datetime.strptime(s,fmt).replace(tzinfo=dt.timezone.utc)
        except ValueError: pass
    return None


def date_part(v, part):
    d = date_value(v)
    if d is None:
        return '' if part == 'rfc3339' else -1
    if part == 'unix': return int(d.timestamp())
    if part == 'rfc3339': return d.isoformat(timespec='seconds').replace('+00:00', 'Z')
    if part == 'yearday': return d.timetuple().tm_yday
    return getattr(d,part)


def split_part(v, sep, i):
    s, sep, i = string(v), string(sep), integer(i)
    pieces = s.split(sep) if sep else list(s)
    if i < 0: i += len(pieces)
    return pieces[i] if 0 <= i < len(pieces) else ''


def regex_part(v, pattern, i):
    s, pattern, i = string(v), string(pattern), integer(i)
    if i == 0: return s
    if i < 0: return ''
    try:
        pieces = re.split(pattern,s,maxsplit=i)
        return pieces[i] if i < len(pieces) else ''
    except re.error: return ''


def pad(left, *args):
    if len(args) < 2: return ''
    s = string(args[0]).encode('utf-8')
    n = max(0, min(10000000, integer(args[1])))
    p = string(args[2]).encode('utf-8') if len(args)>2 else b' '
    if n <= len(s):
        return s[:n].decode('utf-8', 'replace')
    if not p: return s.decode('utf-8','replace')
    count = n-len(s)
    p = (p*((count+len(p)-1)//len(p)))[:count]
    return (p+s if left else s+p).decode('utf-8','replace')


def url_part(v, part, key=''):
    try:
        s = string(v)
        if any(ord(c) < 32 for c in s): return ''
        if re.search(r'%(?![0-9a-fA-F]{2})',s): return ''
        p = urllib.parse.urlsplit(s)
        if part == 'scheme': return p.scheme
        if part == 'host': return p.netloc.split('@')[-1]
        if part == 'port': return str(p.port) if p.port is not None else ''
        if part == 'path': return urllib.parse.unquote(p.path)
        if part == 'fragment': return urllib.parse.unquote(p.fragment)
        if part == 'param': return urllib.parse.parse_qs(p.query,keep_blank_values=True).get(string(key), [''])[0]
    except (ValueError, UnicodeError): return ''
