def translate(sql,conn):
    names=[]
    sql=joins(sql,conn,names)
    sql=arrows(sql,names)
    sql=aggregates(sql,names)
    return sql,names


def original_name(name,replacements):
    for new,old in reversed(replacements):
        name=name.replace(new,old)
    return name
